    private static let locales: Set<String> = ["en", "de", "es", "fr", "it", "ja", "ko", "nl", "pt", "zh"]

    public static func canonicalUrl(_ input: String) throws -> String {
        var raw = input.trimmingCharacters(in: .whitespacesAndNewlines)
        if raw.isEmpty { throw NSError(domain: "path required", code: 1) }
        if raw.contains("\\") || raw.contains("%") { throw NSError(domain: "invalid path", code: 1) }
        if let hash = raw.firstIndex(of: "#") { raw = String(raw[..<hash]) }
        if let query = raw.firstIndex(of: "?") { raw = String(raw[..<query]) }
        let lower = raw.lowercased()
        var path: String
        if lower.hasPrefix("https://") || lower.hasPrefix("http://") || raw.hasPrefix("//") {
            let rest = lower.hasPrefix("https://") ? String(raw.dropFirst(8)) : lower.hasPrefix("http://") ? String(raw.dropFirst(7)) : String(raw.dropFirst(2))
            if let slash = rest.firstIndex(of: "/") {
                let hostport = String(rest[..<slash])
                path = String(rest[slash...])
                if hostport.contains("@") { throw NSError(domain: "userinfo not allowed", code: 1) }
                if hostport.contains(":") { throw NSError(domain: "port not allowed", code: 1) }
                if hostport.lowercased() != host { throw NSError(domain: "host not allowed", code: 1) }
            } else {
                if rest.contains("@") { throw NSError(domain: "userinfo not allowed", code: 1) }
                if rest.contains(":") { throw NSError(domain: "port not allowed", code: 1) }
                if rest.lowercased() != host { throw NSError(domain: "host not allowed", code: 1) }
                path = "/"
            }
        } else if raw.hasPrefix("/") {
            path = raw
        } else {
            path = "/" + raw
        }
        while path.contains("//") { path = path.replacingOccurrences(of: "//", with: "/") }
        path = path.lowercased()
        for seg in path.split(separator: "/", omittingEmptySubsequences: false) {
            if seg == "." || seg == ".." { throw NSError(domain: "path traversal", code: 1) }
        }
        if path.count > 1 { while path.hasSuffix("/") { path.removeLast() } }
        if path.isEmpty { path = "/" }
        if !paths.contains(path) { throw NSError(domain: "unknown path: " + path, code: 1) }
        return path == "/" ? origin + "/" : origin + path
    }

    private static func resolve(_ name: String) throws -> String {
        if let value = pages[name] { return value }
        if let value = blogs[name] { return value }
        if basePaths.contains(name) { return name }
        throw NSError(domain: "unknown page: " + name, code: 1)
    }

    public static func homeUrl() -> String { try! canonicalUrl("/") }
    public static func pageUrl(_ name: String) throws -> String { try canonicalUrl(try resolve(name)) }
    public static func blogUrl(_ slug: String) throws -> String {
        guard let value = blogs[slug] else { throw NSError(domain: "unknown blog: " + slug, code: 1) }
        return try canonicalUrl(value)
    }
    public static func localeUrl(_ locale: String, _ name: String) throws -> String {
        if !locales.contains(locale) { throw NSError(domain: "unknown locale: " + locale, code: 1) }
        let path = try resolve(name)
        if locale == "en" { return try canonicalUrl(path) }
        return try canonicalUrl(path == "/" ? "/" + locale : "/" + locale + path)
    }
}
